-- ====================================================================
-- 南京云顶 PMIS 数据库初始化脚本
-- V1.0.0
-- 对应 PRD V3.2 + 开发计划 V1.0
-- ====================================================================

-- 启用扩展
DO $$
BEGIN
    CREATE EXTENSION IF NOT EXISTS vector;
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'pgvector extension not available, skipping. Agent RAG features will not work.';
END $$;

